      let deliveryLocation, deliveryAddress;
      try {
        deliveryLocation = await window.APServiceCustomerLocation?.ensureForCheckout?.({ user });
        if (!deliveryLocation) { if (submitButton) { submitButton.disabled = false; submitButton.textContent = submitButton.dataset.originalLabel || 'ยืนยันคำสั่งซื้อทั้งหมด'; } return; }
        deliveryAddress = await window.APServiceCustomerAddressBook?.ensureForCheckout?.({ user, location: deliveryLocation });
      } catch (error) {
        if (submitButton) { submitButton.disabled = false; submitButton.textContent = submitButton.dataset.originalLabel || 'ยืนยันคำสั่งซื้อทั้งหมด'; }
        return M.ui.setNotice(error.message || 'ตรวจสอบที่อยู่จัดส่งไม่สำเร็จ กรุณาลองใหม่', 'error');
      }
      if (!deliveryAddress?.id) { if (submitButton) { submitButton.disabled = false; submitButton.textContent = submitButton.dataset.originalLabel || 'ยืนยันคำสั่งซื้อทั้งหมด'; } return M.ui.setNotice('กรุณาเลือกหรือบันทึกที่อยู่จัดส่งก่อนยืนยันออร์เดอร์', 'error'); }
      if (isTransfer && !slipFile) { if (submitButton) { submitButton.disabled = false; submitButton.textContent = submitButton.dataset.originalLabel || 'ยืนยันคำสั่งซื้อทั้งหมด'; } return M.ui.setNotice('กรุณาแนบสลิปโอนเงินก่อนยืนยันออร์เดอร์', 'error'); }
      const groups = Object.values(current.reduce((all, row) => { (all[row.storeId] ||= []).push(row); return all; }, {}));
      const attemptStorageKey = 'apservice.customer.checkout.attempt.v2';
      const attemptFingerprint = JSON.stringify({ addressId: deliveryAddress.id, paymentMethod, groups: groups.map(group => group.map(item => [item.storeId, item.id, item.qty, item.optionKey || ''])), coupons: selectedCoupons() });
      let checkoutNonce = '';
